"circa ± 3-4 punti percentuali": "about ± 3-4 percentage points",
"Esempio: se leggi 18%, il valore vero è più o meno tra 14% e 22%. Non è esatta, ma è ottima per vedere se migliori nel tempo, misurando sempre allo stesso modo.": "Example: if you read 18%, the true value is roughly between 14% and 22%. It is not exact, but it is great for seeing whether you improve over time, if you always measure the same way.",
"Valore scritto da te nel campo Massa grassa. Le bilance con le placche sbagliano di circa ± 4-5 punti; il plicometro, fatto da un esperto, circa ± 3-4 punti.": "The value you entered in the Body fat field. Scales with metal pads are off by about ± 4-5 points; a skinfold caliper used by an expert by about ± 3-4 points.",
"Massa magra = peso − grasso (muscoli, ossa, organi e acqua).": "Lean mass = weight − fat (muscles, bones, organs and water).",
