"Tocca ogni campo per vedere dove si misura.": "Tap each field to see where to measure.",
"L'altezza serve per calcolare l'IMC (indice di massa corporea) e la massa grassa. Il sesso serve per la formula della massa grassa.": "Height is used to calculate BMI (body mass index) and body fat. Sex is used for the body fat formula.",
"Come pesarti": "How to weigh yourself",
"La mattina, dopo il bagno e prima di colazione, senza scarpe e con pochi vestiti.": "In the morning, after the bathroom and before breakfast, barefoot and in light clothes.",
"Sempre la stessa bilancia, appoggiata su un pavimento duro.": "Always the same scale, on a hard floor.",
"Come misurare la vita": "How to measure your waist",
"In piedi, pancia rilassata. Metro a metà tra l'ultima costola e l'osso del bacino (di solito all'altezza dell'ombelico), dritto e parallelo al pavimento.": "Standing, belly relaxed. Tape halfway between your lowest rib and your hip bone (usually at navel height), straight and parallel to the floor.",
"Misura alla fine di un respiro normale, senza trattenere il fiato né tirare in dentro la pancia.": "Measure at the end of a normal breath, without holding your breath or sucking in your belly.",
"Come misurare i fianchi": "How to measure your hips",
"In piedi, piedi uniti. Metro nel punto più largo dei glutei, dritto e parallelo al pavimento.": "Standing, feet together. Tape around the widest part of your buttocks, straight and parallel to the floor.",
"Guardati di lato allo specchio per trovare il punto più sporgente.": "Look at yourself sideways in the mirror to find the widest point.",
"Come misurare il petto": "How to measure your chest",
"Braccia lungo i fianchi. Metro sotto le ascelle, sulla linea dei capezzoli, dritto anche sulla schiena.": "Arms by your sides. Tape under your armpits, across the nipple line, straight across your back too.",
"Misura a respiro normale, senza gonfiare il petto.": "Measure while breathing normally, without puffing out your chest.",
"Come misurare il braccio": "How to measure your arm",
"Braccio rilassato lungo il fianco. Metro a metà tra spalla e gomito, nel punto più grosso.": "Arm relaxed by your side. Tape halfway between shoulder and elbow, at the thickest point.",
"Misura sempre lo stesso braccio (per esempio il destro).": "Always measure the same arm (for example the right one).",
"Come misurare la coscia": "How to measure your thigh",
"In piedi, peso su tutte e due le gambe. Metro appena sotto il gluteo, nel punto più grosso della coscia.": "Standing, weight on both legs. Tape just below the buttock, at the thickest point of the thigh.",
"Misura sempre la stessa gamba (per esempio la destra).": "Always measure the same leg (for example the right one).",
"Come misurare il collo": "How to measure your neck",
"Testa dritta, sguardo in avanti, spalle rilassate. Metro appena sotto il pomo d'Adamo, leggermente inclinato in giù verso davanti.": "Head straight, eyes forward, shoulders relaxed. Tape just below the Adam's apple, sloping slightly down toward the front.",
"Serve, insieme alla vita, per stimare la massa grassa.": "Together with the waist, it is used to estimate body fat.",
"Come misurare l'altezza": "How to measure your height",
"Senza scarpe, schiena e talloni contro il muro, sguardo dritto. Appoggia un libro piatto sulla testa, segna il muro e misura da terra al segno.": "Barefoot, back and heels against the wall, looking straight ahead. Rest a flat book on your head, mark the wall and measure from the floor to the mark.",
"Basta misurarla una volta.": "Measuring it once is enough.",
"Facoltativa. Se hai una bilancia con le placche di metallo (impedenziometrica) o il plicometro, scrivi qui il valore. Se no lascia vuoto: l'app la stima da vita e collo.": "Optional. If you have a scale with metal pads (bioimpedance) or a skinfold caliper, enter the value here. If not, leave it empty: the app estimates it from waist and neck.",
"È sempre una stima: usa lo stesso strumento, alla stessa ora, e guarda come cambia nel tempo.": "It is always an estimate: use the same tool, at the same time of day, and watch how it changes over time.",
"Usa un metro morbido da sarta: aderente alla pelle, senza stringere.": "Use a soft tailor's tape: snug against the skin, without squeezing.",
