"Tira la barra fino all'altezza del mento o della parte alta del petto (non serve toccare il petto): i gomiti scendono tenendosi un po' in avanti, non troppo di lato, per proteggere la spalla.": "Pull the bar down to chin or upper-chest height (no need to touch your chest): elbows come down staying slightly forward, not too far out to the side, to protect your shoulder.",
"Risali lentamente fino a braccia distese: in alto è normale che i gomiti si aprano.": "Go back up slowly until your arms are straight: at the top it's normal for the elbows to open.",
"Busto quasi dritto con carichi leggeri. Quando il carico aumenta è normale inclinarsi un po' indietro e inarcare di più la schiena per aiutarti nelle ultime ripetizioni (si dice \"rubare\"), come succede anche nelle trazioni. Fallo sempre con controllo, senza dondolare.": "Torso almost upright with light loads. As the load goes up it's normal to lean back a little and arch your back more to help with the last reps (called \"cheating\"), just like in pull-ups. Always do it under control, without swinging.",
