"Spalle e schiena": "Shoulders and back",
"Postura dritta e spalle forti": "Upright posture and strong shoulders",
"Da 0 a 6 mesi di palestra. 3 giorni a settimana alternando A e B (es. lun-mer-ven). Ripetizioni 10–15, chiudi ogni serie con 2–3 ripetizioni ancora in canna. Quando fai tutte le serie al massimo delle ripetizioni, aumenta il peso di poco.": "From 0 to 6 months in the gym. 3 days a week alternating A and B (e.g. Mon-Wed-Fri). 10–15 reps, end each set with 2–3 reps still in the tank. When you do all sets at the top of the rep range, increase the weight a little.",
"Da 6 mesi a 2 anni. 4 giorni: Alta A, Bassa A, riposo, Alta B, Bassa B. Ogni muscolo lavora 2 volte a settimana. Chiudi le serie con 1–2 ripetizioni in canna. Ogni 6–8 settimane fai una settimana leggera con metà delle serie.": "From 6 months to 2 years. 4 days: Upper A, Lower A, rest, Upper B, Lower B. Each muscle works 2 times a week. End your sets with 1–2 reps in the tank. Every 6–8 weeks do a light week with half the sets.",
"Esperto": "Advanced",
"Oltre 2 anni. 5 giorni: Forza alta, Forza bassa, riposo, Spinta, Tirata, Gambe e glutei. Sui primi esercizi di forza fai la prima serie più pesante (4–6), poi le altre con il 10% in meno. Blocchi di 4–6 settimane, poi 1 settimana leggera.": "Over 2 years. 5 days: Upper strength, Lower strength, rest, Push, Pull, Legs and glutes. On the first strength exercises make the first set heavier (4–6), then the others with 10% less. Blocks of 4–6 weeks, then 1 light week.",
