"Esperto · Gambe e glutei": "Advanced · Legs and glutes",
"Glutei, cosce, interno-esterno coscia, addome": "Glutes, thighs, inner-outer thigh, abs",
"Per chi inizia. 3 giorni a settimana alternando A e B (es. lun-mer-ven). Ti servono una sedia, un tavolo robusto e un asciugamano. 2–3 serie da 10–20 ripetizioni, lasciandone 2–3 in canna. Scendi sempre lentamente (3 secondi).": "For beginners. 3 days a week alternating A and B (e.g. Mon-Wed-Fri). You need a chair, a sturdy table and a towel. 2–3 sets of 10–20 reps, leaving 2–3 in the tank. Always lower slowly (3 seconds).",
"Dopo 2–3 mesi. 4 giorni: Alta A, Bassa A, riposo, Alta B, Bassa B. Chiudi ogni serie con 1–2 ripetizioni in canna. Quando superi 20–25 ripetizioni, passa alla versione più dura indicata nell'esercizio.": "After 2–3 months. 4 days: Upper A, Lower A, rest, Upper B, Lower B. End each set with 1–2 reps in the tank. When you go past 20–25 reps, move on to the harder version shown in the exercise.",
"Per chi è già allenato. 4 giorni: Spinta, Tirata, riposo, Gambe davanti, Gambe dietro. Serie quasi al limite (0–1 in canna) con le versioni più dure: piedi rialzati, una gamba, discesa in 4 secondi, pause in basso, «una e mezza» (scendi, risali a metà, riscendi, poi su). Ogni 6 settimane una settimana leggera con metà serie.": "For people already trained. 4 days: Push, Pull, rest, Front legs, Back legs. Sets close to the limit (0–1 in the tank) with the harder versions: feet raised, one leg, 4-second lowering, pauses at the bottom, \"one and a half\" (go down, come halfway up, go down again, then up). Every 6 weeks a light week with half the sets.",
