"Perché funziona anche senza pesi:": "Why it works even without weights:",
"Il muscolo cresce anche con carichi leggeri": "Muscle grows even with light loads",
", se la serie arriva vicino al limite: con 20–30 ripetizioni i risultati sono quasi uguali a quelli con pesi pesanti. Schoenfeld e coll., J Strength Cond Res 2017; Lopez e coll., Med Sci Sports Exerc 2021.": ", if the set gets close to the limit: with 20–30 reps the results are almost the same as with heavy weights. Schoenfeld et al., J Strength Cond Res 2017; Lopez et al., Med Sci Sports Exerc 2021.",
"I piegamenti valgono quanto la panca piana": "Push-ups are as good as the bench press",
"per forza e massa del petto, a parità di fatica. Calatayud e coll., J Strength Cond Res 2015; Kikuchi e Nakazato, J Exerc Sci Fit 2017; Kotarsky e coll., J Strength Cond Res 2018.": "for chest strength and size, at equal effort. Calatayud et al., J Strength Cond Res 2015; Kikuchi and Nakazato, J Exerc Sci Fit 2017; Kotarsky et al., J Strength Cond Res 2018.",
"Quante serie": "How many sets",
": almeno 10 a settimana per muscolo; di più dà un po' di più, ma con meno guadagno per serie. Pelland e coll., Sports Med 2025; ACSM, posizione ufficiale sull'allenamento con sovraccarichi 2026.": ": at least 10 a week per muscle; more gives a little more, but with less gain per set. Pelland et al., Sports Med 2025; ACSM, official position stand on resistance training 2026.",
"Quanto vicino al limite": "How close to the limit",
": 0–3 ripetizioni in canna, più vicino per chi è esperto. Robinson e coll., Sports Med 2024.": ": 0–3 reps in the tank, closer for experienced lifters. Robinson et al., Sports Med 2024.",
"Come progredire senza pesi": "How to progress without weights",
": versione più dura, discesa più lenta, pause, una gamba o un braccio alla volta. È il metodo delle «progressioni» della ginnastica a corpo libero (Low, Overcoming Gravity).": ": harder version, slower lowering, pauses, one leg or one arm at a time. It's the \"progressions\" method of bodyweight gymnastics (Low, Overcoming Gravity).",
": nei programmi che lo usano gli strappi ai femorali calano circa della metà. van Dyk e coll., Br J Sports Med 2019.": ": in programmes that use it, hamstring strains drop by about half. van Dyk et al., Br J Sports Med 2019.",
"Il minimo per la salute": "The minimum for health",
": esercizi di forza almeno 2 giorni a settimana. OMS, linee guida 2020; Momma e coll., Br J Sports Med 2022.": ": strength exercises at least 2 days a week. WHO guidelines 2020; Momma et al., Br J Sports Med 2022.",
