"Prima di iniziare fai 1 serie facile con metà delle ripetizioni, o la versione più semplice, per preparare muscoli e articolazioni.": "Before starting do 1 easy set with half the reps, or the easier version, to prepare your muscles and joints.",
"Prima di iniziare fai 1–2 serie leggere, con circa metà del peso, per preparare muscoli e articolazioni.": "Before starting do 1–2 light sets, with about half the weight, to prepare your muscles and joints.",
"Quando fai {*} ripetizioni in tutte le serie, togli un po' di contrappeso: la macchina ti aiuta meno. L'obiettivo è arrivare alle trazioni senza aiuto.": "When you do {*} reps on every set, remove a little counterweight: the machine helps you less. The goal is to get to pull-ups without assistance.",
"Quando fai il numero massimo di ripetizioni ({*}) in tutte le serie, rendi l'esercizio più difficile: scendi più lentamente, aggiungi qualche ripetizione o passa a una versione più dura.": "When you do the maximum number of reps ({*}) on every set, make the exercise harder: lower more slowly, add a few reps or move on to a harder version.",
"Resta sullo stesso peso finché fai il numero massimo di ripetizioni ({*}) in tutte le serie. Allora aumenta di poco: 1–2,5 kg per braccia e spalle, 2,5–5 kg per gambe e schiena.": "Stay on the same weight until you do the maximum number of reps ({*}) on every set. Then increase a little: 1–2.5 kg for arms and shoulders, 2.5–5 kg for legs and back.",
"Riscaldamento": "Warm-up",
"Quanto faticare": "How hard to push",
"Chiudi ogni serie quando potresti fare ancora 1–2 ripetizioni fatte bene. Se ne potresti fare 5 in più, il peso è troppo leggero.": "End each set when you could still do 1–2 good reps. If you could do 5 more, the weight is too light.",
