"Collegamento non riuscito, riprovo…": "Connection failed, trying again…",
"Nessun cardio trovato o scelto. Indossa la fascia (si accende col contatto della pelle, meglio se inumidisci gli elettrodi) oppure attiva la \"trasmissione battito\" sull'orologio, poi riprova.": "No heart rate monitor found or chosen. Put on the strap (it turns on with skin contact, better if you moisten the electrodes) or turn on \"heart rate broadcast\" on your watch, then try again.",
"Permesso Bluetooth negato. Accendi Bluetooth e posizione del telefono e consenti l'accesso quando Chrome lo chiede.": "Bluetooth permission denied. Turn on your phone's Bluetooth and location and allow access when Chrome asks.",
