"Puoi dire: fatta. Dodici ripetizioni. Quaranta chili. Salta. Pausa. Riprendi. Altri quindici secondi. Salta esercizio. Ripeti. Battito. Musica. Fine.": "You can say: done. Twelve reps. Forty kilos. Skip. Pause. Resume. Fifteen more seconds. Skip exercise. Repeat. Heart rate. Music. Finish.",
"Non hai canzoni salvate.": "You have no saved songs.",
"Vuoi chiudere l'allenamento? Di' sì per confermare, o no per continuare.": "Do you want to end the workout? Say yes to confirm, or no to carry on.",
"Ok, continuiamo.": "OK, let's carry on.",
"Ripartiamo. Quando finisci la serie di' fatta.": "Let's go again. When you finish the set say done.",
"Sei in pausa. Di' riprendi per ripartire.": "You're paused. Say resume to start again.",
"Recupero in pausa.": "Rest paused.",
