"In pausa. Di' riprendi quando vuoi ripartire.": "Paused. Say resume when you want to start again.",
"Quante ripetizioni hai fatto?": "How many reps did you do?",
"Per saltare l'esercizio di' salta esercizio. Quando finisci la serie di' fatta.": "To skip the exercise say skip exercise. When you finish the set say done.",
"Il microfono è bloccato. Tocca il lucchetto vicino all'indirizzo (o Impostazioni sito di Chrome) e consenti il microfono.": "The microphone is blocked. Tap the padlock next to the address (or Chrome's Site settings) and allow the microphone.",
