": un nutrizionista, un dietista o un medico dietologo. Non improvvisare e non copiare diete da internet, dai social o dagli amici: quello che va bene per un altro può farti male.": ": a nutritionist, a dietitian or a doctor. Don't improvise and don't copy diets from the internet, social media or friends: what works for someone else can harm you.",
"Se hai problemi di salute (diabete, pressione, cuore, reni, allergie) parlane sempre anche con il tuo medico.": "If you have health problems (diabetes, blood pressure, heart, kidneys, allergies) always talk to your doctor too.",
"Qui sotto scrivi o fotografi il piano che ti ha dato il professionista, così lo hai sempre con te, anche senza internet.": "Below, write or photograph the plan your professional gave you, so you always have it with you, even without internet.",
"Tocca un bicchiere ogni volta che bevi. Di solito servono 8-10 bicchieri al giorno, di più quando ti alleni o fa caldo.": "Tap a glass every time you drink. Usually you need 8-10 glasses a day, more when you train or it's hot.",
