"Copia il backup e incollalo in un posto sicuro (una nota o un messaggio a te stesso). Se cambi telefono, lo incolli qui sotto e ritrovi tutto. I video caricati non sono inclusi.": "Copy the backup and paste it somewhere safe (a note or a message to yourself). If you change phone, paste it below and you'll get everything back. Uploaded videos aren't included.",
