"Fai una foto alla scheda che ti ha scritto il personal trainer. L'app riconosce gli esercizi, le serie, le ripetizioni e il recupero. Prima di salvare puoi controllare e correggere tutto.": "Take a photo of the workout your personal trainer wrote for you. The app recognises the exercises, sets, reps and rest. Before saving you can check and correct everything.",
