"Riconosci gli esercizi": "Recognise the exercises",
"Non ho trovato esercizi. Prova a scrivere un esercizio per riga, ad esempio \"Panca piana 4x8\".": "I didn't find any exercises. Try writing one exercise per line, for example \"Bench press 4x8\".",
"Troppe richieste, aspetta un minuto e riprova.": "Too many requests, wait a minute and try again.",
"Non sono riuscito a leggere bene la foto. Ho messo qui sotto quello che ho letto: correggilo e premi \"Riconosci gli esercizi\".": "I couldn't read the photo well. I've put what I read below: correct it and press \"Recognise the exercises\".",
"Per leggere la foto serve internet. In alternativa usa Google Lens: apri la foto, premi Testo, Copia, e incollalo qui sotto.": "Reading the photo needs internet. Alternatively use Google Lens: open the photo, press Text, Copy, and paste it below.",
"Li ho riconosciuti tutti.": "I recognised them all.",
"Ne ho riconosciuti {*}. Quelli in giallo scegli tu a quale esercizio corrispondono, oppure lasciali su \"salta\".": "I recognised {*}. For the ones in yellow choose which exercise they match, or leave them on \"skip\".",
