"La tua testa allenata": "Your trained mind",
"Mental coach": "Mental coach",
"Una voce che ti incoraggia in palestra, a casa e nella corsa, festeggia i progressi e ti aiuta a non mollare. Tutto basato sugli studi di psicologia dello sport.": "A voice that encourages you at the gym, at home and on your runs, celebrates your progress and helps you not give up. All based on sports psychology studies.",
"Come stai andando": "How you're doing",
"Giorno su 66": "Day out of 66",
"Settimane ok di fila": "Good weeks in a row",
"Verso l'abitudine (66 giorni)": "Towards the habit (66 days)",
"Il tuo perché": "Your why",
"Una frase vera, tua. Il coach te la ricorda all'inizio di ogni allenamento.": "A true sentence, your own. The coach reminds you of it at the start of every workout.",
"Obiettivo della settimana": "Weekly goal",
"Allenamenti a settimana (palestra, casa e corsa)": "Workouts a week (gym, home and running)",
"Meglio un obiettivo che riesci a mantenere: 2 o 3 per iniziare, poi sali.": "Better a goal you can keep: 2 or 3 to start, then go up.",
"Quando e dove": "When and where",
"Ora": "Time",
"Piano B: se… allora…": "Plan B: if… then…",
"Decidi adesso cosa fare se qualcosa va storto. Tocca un esempio per aggiungerlo o scrivi il tuo.": "Decide now what to do if something goes wrong. Tap an example to add it or write your own.",
"Aggiungi": "Add",
"Le tue frasi": "Your phrases",
"Il coach le dice durante l'allenamento: all'ultima serie, a metà sessione, ogni tanto nel recupero e ogni 2 km di corsa. Scegli quelle che ti piacciono.": "The coach says them during your workout: on the last set, halfway through the session, now and then during rest and every 2 km of a run. Choose the ones you like.",
"Per darti la carica": "To fire you up",
"Per la tecnica": "For technique",
"Per la corsa": "For running",
"Visualizzazione": "Visualisation",
"Un minuto a voce prima di iniziare: ti calmi, immagini l'allenamento fatto bene e ti concentri. Puoi farla anche nello spogliatoio.": "One minute of voice before you start: you calm down, imagine the workout done well and focus. You can do it in the changing room too.",
"Su cosa si basa il coach": "What the coach is based on",
"Coach attivo. Ci sono io con te.": "Coach on. I'm here with you.",
