"{*} L'IMC non distingue muscoli e grasso: chi ha molti muscoli può risultare \"sovrappeso\". Il giro vita dice di più.": "{*} BMI doesn't tell muscle from fat: people with lots of muscle can come out as \"overweight\". Your waist says more.",
"{*}. Per crescere ne servono almeno 10 a settimana per muscolo. Vedi la mappa nel": "{*}. To grow you need at least 10 a week per muscle. See the map in",
