"Punta a perdere dallo 0,5 all'1% del peso a settimana{*}. Più veloce si perde anche muscolo.": "Aim to lose 0.5 to 1% of your weight a week{*}. Faster than that you lose muscle too.",
"Ne servono di più che da giovani: almeno 1,0–1,2 g per kg al giorno{*}": "You need more than when you were young: at least 1.0–1.2 g per kg a day{*}",
"Ne servono di più che da giovani: almeno 1,0–1,2 g per kg al giorno{*}.": "You need more than when you were young: at least 1.0–1.2 g per kg a day{*}.",
