"Ripristino fatto: {*} {*}. Niente di quello che avevi è stato cancellato.": "Restore done: {*} {*}. Nothing you had was deleted.",
"Preparo il file…": "Preparing the file…",
"Fatto. Il file \"{*}\" è nella cartella Download del telefono. Tienilo: serve se cambi telefono o cancelli i dati.": "Done. The file \"{*}\" is in the phone's Download folder. Keep it: you need it if you change phone or clear your data.",
