"Mobilità e stretching": "Mobility and stretching",
"Riscaldamento prima, allungamenti dopo, guidati a voce": "Warm-up before, stretches after, voice-guided",
"Fai prima 5 minuti di cardio leggero (tapis roulant, cyclette, saltelli). Quando inizi un piano, l'app te lo propone da sola dopo il cardio.": "First do 5 minutes of light cardio (treadmill, exercise bike, jumping jacks). When you start a plan, the app suggests it by itself after the cardio.",
"Dopo l'allenamento": "After your workout",
"Tieni ogni posizione senza molleggiare. Devi sentire tirare, mai dolore.": "Hold each position without bouncing. You should feel a pull, never pain.",
"Giorni di riposo": "Rest days",
"· per lato": "· per side",
"Prima dell'allenamento: movimenti dinamici per scaldare muscoli e articolazioni. Dopo: allungamenti fermi e respiro lento. Una voce ti guida, conta il tempo e ti dice quando cambiare lato.": "Before your workout: dynamic movements to warm up muscles and joints. After: static stretches and slow breathing. A voice guides you, counts the time and tells you when to switch sides.",
