"Le foto restano solo su questo telefono.": "The photos stay only on this phone.",
"Non vanno su internet, non vengono inviate a nessuno e nessuno le può vedere: né chi ha fatto l'app né altri. Le vedi solo tu, qui dentro.": "They don't go on the internet, they aren't sent to anyone and nobody can see them: not the people who made the app, nor anyone else. Only you can see them, in here.",
