"Nessuna foto. È del tutto facoltativo: aggiungile solo se ti va, servono solo a te per vedere i progressi.": "No photos. It's completely optional: add them only if you want, they're just for you to see your progress.",
"🔒 PIN attivo": "🔒 PIN on",
