"Utile se presti il telefono a qualcuno. Scegli un PIN di 4 cifre (o più) e ricordalo: se lo dimentichi, per sbloccare bisogna cancellare le foto.": "Useful if you lend your phone to someone. Choose a PIN of 4 digits (or more) and remember it: if you forget it, you have to delete the photos to unlock.",
"Attiva": "Turn on",
"Posa": "Pose",
"Aggiungi una foto": "Add a photo",
