"📷 Scatta ora": "📷 Take one now",
"🖼 Dalla galleria": "🖼 From the gallery",
"Consiglio: stessa luce, stesso posto, stessa distanza, possibilmente la mattina. Così il confronto è fedele. Se la prendi dalla galleria, una copia resta anche lì: puoi cancellarla dalla galleria dopo averla aggiunta.": "Tip: same light, same place, same distance, ideally in the morning. That way the comparison is accurate. If you pick it from the gallery, a copy stays there too: you can delete it from the gallery after adding it.",
"Il PIN deve avere da 4 a 8 cifre.": "The PIN must have 4 to 8 digits.",
"I due PIN non sono uguali.": "The two PINs don't match.",
"PIN attivato. Le foto si bloccano quando esci dall'app.": "PIN turned on. The photos lock when you leave the app.",
"Includi anche le foto del corpo": "Include the body photos too",
"Di solito è meglio lasciarlo spento: chi ha il file potrebbe vedere le foto. Accendilo solo se il file resta tuo (per esempio quando cambi telefono). Il file diventa più grande.": "It's usually better to leave this off: whoever has the file could see the photos. Turn it on only if the file stays yours (for example when you change phone). The file gets bigger.",
"Per includere le foto del corpo, prima sbloccale con il PIN (qui sopra, in \"Foto dei progressi\").": "To include the body photos, first unlock them with the PIN (above, in \"Progress photos\").",
