"lun-mer-ven).": "Mon-Wed-Fri).",
"Ripetizioni 10–15, chiudi ogni serie con 2–3 ripetizioni ancora in canna.": "10–15 reps, end each set with 2–3 reps still in the tank.",
"Quando fai tutte le serie al massimo delle ripetizioni, aumenta il peso di poco.": "When you do all sets at the top of the rep range, increase the weight a little.",
"Da 6 mesi a 2 anni.": "From 6 months to 2 years.",
"4 giorni: Alta A, Bassa A, riposo, Alta B, Bassa B.": "4 days: Upper A, Lower A, rest, Upper B, Lower B.",
"Ogni muscolo lavora 2 volte a settimana.": "Each muscle works 2 times a week.",
"Chiudi le serie con 1–2 ripetizioni in canna.": "End your sets with 1–2 reps in the tank.",
"Ogni 6–8 settimane fai una settimana leggera con metà delle serie.": "Every 6–8 weeks do a light week with half the sets.",
"Oltre 2 anni.": "Over 2 years.",
"5 giorni: Forza alta, Forza bassa, riposo, Spinta, Tirata, Gambe e glutei.": "5 days: Upper strength, Lower strength, rest, Push, Pull, Legs and glutes.",
"Sui primi esercizi di forza fai la prima serie più pesante (4–6), poi le altre con il 10% in meno.": "On the first strength exercises make the first set heavier (4–6), then the others with 10% less.",
"Blocchi di 4–6 settimane, poi 1 settimana leggera.": "Blocks of 4–6 weeks, then 1 light week.",
"Per chi inizia.": "For beginners.",
"Ti servono una sedia, un tavolo robusto e un asciugamano.": "You need a chair, a sturdy table and a towel.",
"2–3 serie da 10–20 ripetizioni, lasciandone 2–3 in canna.": "2–3 sets of 10–20 reps, leaving 2–3 in the tank.",
"Scendi sempre lentamente (3 secondi).": "Always lower slowly (3 seconds).",
"Dopo 2–3 mesi.": "After 2–3 months.",
"Chiudi ogni serie con 1–2 ripetizioni in canna.": "End each set with 1–2 reps in the tank.",
"Quando superi 20–25 ripetizioni, passa alla versione più dura indicata nell'esercizio.": "When you go past 20–25 reps, move on to the harder version shown in the exercise.",
"Per chi è già allenato.": "For people already trained.",
"4 giorni: Spinta, Tirata, riposo, Gambe davanti, Gambe dietro.": "4 days: Push, Pull, rest, Front legs, Back legs.",
"Serie quasi al limite (0–1 in canna) con le versioni più dure: piedi rialzati, una gamba, discesa in 4 secondi, pause in basso, «una e mezza» (scendi, risali a metà, riscendi, poi su).": "Sets close to the limit (0–1 in the tank) with the harder versions: feet raised, one leg, 4-second lowering, pauses at the bottom, \"one and a half\" (go down, come halfway up, go down again, then up).",
"Ogni 6 settimane una settimana leggera con metà serie.": "Every 6 weeks a light week with half the sets.",
", se la serie arriva vicino al limite: con 20–30 ripetizioni i risultati sono quasi uguali a quelli con pesi pesanti.": ", if the set gets close to the limit: with 20–30 reps the results are almost the same as with heavy weights.",
