"Di' inizio allenamento.": "Say start workout.",
"Serve internet e il permesso del microfono.": "Needs internet and microphone permission.",
"Funziona meglio con Chrome su Android.": "Works best with Chrome on Android.",
"Lo schermo deve restare acceso.": "The screen must stay on.",
"Ciao!": "Hi!",
"Serie 1 di 3, Leg Press, 10 ripetizioni.": "Set 1 of 3, Leg Press, 10 reps.",
"Inspira mentre scendi, espira mentre spingi.": "Breathe in as you lower, breathe out as you push.",
"Ogni serie in più a settimana per muscolo aggiunge crescita, ma oltre le 20 il guadagno in più è piccolo.": "Each extra weekly set per muscle adds growth, but past 20 the extra gain is small.",
"Le linee guida dell'American College of Sports Medicine consigliano almeno 10 serie a settimana per muscolo.": "The American College of Sports Medicine guidelines recommend at least 10 sets a week per muscle.",
"Già con circa 4 serie a settimana un muscolo cresce un po', e per mantenerlo ne bastano poche se il peso resta impegnativo.": "With about 4 sets a week a muscle already grows a little, and to maintain it a few are enough if the weight stays challenging.",
"Per questo sotto le 4 il muscolo è segnato in rosso.": "That's why under 4 the muscle is marked in red.",
"Pelland e coll.": "Pelland et al.",
"2025 · Spiering e coll., J Strength Cond Res 2021": "2025 · Spiering et al., J Strength Cond Res 2021",
"Ognuno risponde in modo diverso.": "Everyone responds differently.",
"Allenatori esperti come Mike Israetel parlano di \"volume minimo\" e \"volume massimo recuperabile\" diversi per ogni persona e ogni muscolo: sono indicazioni pratiche, non misure di laboratorio.": "Experienced coaches like Mike Israetel talk about \"minimum volume\" and \"maximum recoverable volume\" that differ for each person and each muscle: they are practical guidelines, not lab measurements.",
"Chi inizia cresce anche con meno serie.": "Beginners grow even with fewer sets.",
"Aumentare le ripetizioni o aumentare il peso fanno crescere il muscolo allo stesso modo.": "Adding reps or adding weight build muscle the same way.",
"L'app usa la \"doppia progressione\": quando arrivi al massimo delle ripetizioni in tutte le serie, sali di peso.": "The app uses \"double progression\": when you reach the top of the rep range on every set, you go up in weight.",
"La linea guida consiglia un aumento del 2–10% quando superi l'obiettivo di ripetizioni.": "The guideline recommends a 2–10% increase when you exceed the rep target.",
"L'app sale fino al 5% per petto, schiena, spalle e braccia e fino al 10% per le gambe, arrotondando ai pesi che trovi in palestra (2,5 kg; manubri di 2 in 2, di 1 in 1 sotto i 10 kg).": "The app goes up to 5% for chest, back, shoulders and arms and up to 10% for legs, rounding to the weights you find in the gym (2.5 kg; dumbbells in steps of 2, steps of 1 under 10 kg).",
"La linea guida aspetta 2 allenamenti di fila: l'app sale dopo 1, come negli studi sulla doppia progressione.": "The guideline waits for 2 workouts in a row: the app goes up after 1, as in the double-progression studies.",
"Se le serie ti sono sembrate facili (ne avresti fatte più di 3 in più) puoi salire prima; se ti fa male qualcosa, non salire.": "If the sets felt easy (you could have done more than 3 extra) you can go up sooner; if something hurts, don't go up.",
"Il massimale stimato usa la formula di Epley: è un'approssimazione, meno precisa sopra le 10 ripetizioni.": "The estimated max uses the Epley formula: it's an approximation, less accurate above 10 reps.",
"Tutti i muscoli principali hanno almeno 4 serie questa settimana.": "All the main muscles have at least 4 sets this week.",
"per ogni muscolo.": "for each muscle.",
"Conta 1 serie per il muscolo che lavora di più e ½ per quelli che aiutano.": "Counts 1 set for the muscle that works most and ½ for the helpers.",
"La zona tratteggiata è l'obiettivo di 10–20 serie.": "The dashed area is the 10–20 set target.",
"Avambracci, obliqui, lombari e adduttori lavorano già negli altri esercizi: non sono mai segnati in rosso.": "Forearms, obliques, lower back and adductors already work in other exercises: they're never marked in red.",
"Da 3 allenamenti non migliori su questo esercizio.": "You haven't improved on this exercise for 3 workouts.",
"Capita: fai una settimana leggera (metà delle serie, stesso peso) e poi riparti.": "It happens: do a light week (half the sets, same weight) and then start again.",
