"lun-mer-ven)": "Mon-Wed-Fri)",
"Per chi parte da zero.": "For those starting from zero.",
"Alterni corsa lenta e camminata: in 9 settimane arrivi a correre 30 minuti di fila.": "You alternate slow running and walking: in 9 weeks you'll run 30 minutes non-stop.",
"Corri così piano da riuscire a parlare.": "Run slowly enough to be able to talk.",
"Se una settimana ti è sembrata dura, ripetila: va benissimo.": "If a week felt hard, repeat it: that's absolutely fine.",
"4 uscite a settimana (es.": "4 sessions a week (e.g.",
"lun, mer, ven, dom col lungo)": "Mon, Wed, Fri, Sun with the long run)",
"Per chi corre già 30 minuti di fila.": "For those who already run 30 minutes non-stop.",
"3 uscite su 4 sono facili e 1 è veloce: è la regola 80/20.": "3 sessions out of 4 are easy and 1 is fast: it's the 80/20 rule.",
"Le settimane 4 e 8 sono più leggere per recuperare.": "Weeks 4 and 8 are lighter to recover.",
"Il lungo cresce al massimo del 10%.": "The long run grows by at most 10%.",
"Per chi corre già 4–5 volte a settimana con un lungo di almeno 65 minuti.": "For those who already run 4–5 times a week with a long run of at least 65 minutes.",
"Due sedute dure (intervalli 4×4 e soglia), il resto facile: circa 80% facile e 20% duro.": "Two hard sessions (4×4 intervals and threshold), the rest easy: about 80% easy and 20% hard.",
"Settimane 4 e 8 più leggere.": "Weeks 4 and 8 lighter.",
"Per correre i 5 km più veloce.": "To run 5 km faster.",
"Serve già correre 30 minuti di fila.": "You need to be able to run 30 minutes non-stop already.",
"Una seduta veloce, una facile e un lungo.": "One fast session, one easy and one long run.",
"L'ultima settimana è più leggera e finisce con la prova sui 5 km: il GPS ti dice quando arrivi.": "The last week is lighter and ends with the 5 km test: the GPS tells you when you get there.",
"Per preparare i 10 km.": "To prepare for 10 km.",
"Serve correre già 3 volte a settimana e almeno 45 minuti di fila.": "You need to already run 3 times a week and at least 45 minutes non-stop.",
"Intervalli e soglia a settimane alterne, il resto facile.": "Intervals and threshold in alternate weeks, the rest easy.",
"Ultima settimana di scarico e prova sui 10 km.": "Last week is a taper with the 10 km test.",
"Per perdere peso muovendoti tanto ma senza farti male: soprattutto camminata svelta, poi brevi tratti di corsetta.": "To lose weight moving a lot but without getting hurt: mostly brisk walking, then short jogs.",
"Si parte da 150 minuti a settimana e si arriva a 300.": "You start from 150 minutes a week and build up to 300.",
"Da solo il movimento fa perdere poco peso: conta soprattutto l'alimentazione (scheda Dieta e un nutrizionista).": "Exercise alone makes you lose little weight: diet matters most (Diet tab and a nutritionist).",
"Insieme funzionano meglio e aiutano a non riprendere i chili.": "Together they work better and help you keep the weight off.",
"Per arrivare a correre i 21 km.": "To get to running 21 km.",
"Serve correre già 3–4 volte a settimana con un lungo di almeno 55 minuti.": "You need to already run 3–4 times a week with a long run of at least 55 minutes.",
"Il lungo arriva a 100 minuti, poi 2 settimane di scarico e la prova sui 21,1 km.": "The long run builds to 100 minutes, then 2 taper weeks and the 21.1 km test.",
"Gli atleti di resistenza più forti fanno circa l'80% degli allenamenti piano e il 20% duro.": "The best endurance athletes do about 80% of their training easy and 20% hard.",
"Negli studi questo schema migliora il fiato almeno quanto, o più, di fare tutto a ritmo medio.": "In studies this pattern improves fitness at least as much as, or more than, doing everything at a medium pace.",
"Nei principianti chi aumentava i km di oltre il 30% in due settimane si infortunava di più.": "Among beginners, those who increased their km by more than 30% in two weeks got injured more.",
"Una singola uscita più lunga del 10% rispetto alla più lunga dell'ultimo mese aumenta il rischio: per questo il lungo cresce poco alla volta.": "A single run 10% longer than the longest of the last month raises the risk: that's why the long run grows a little at a time.",
"In uno studio un programma che cresceva del 10% non ha dato meno infortuni di uno un po' più veloce.": "In one study a programme growing by 10% didn't give fewer injuries than a slightly faster one.",
"Conta soprattutto non fare salti grandi e ascoltare il corpo.": "What matters most is avoiding big jumps and listening to your body.",
"= 208 − 0,7 × età.": "= 208 − 0.7 × age.",
"È una stima: per alcune persone sbaglia anche di 10 battiti, quindi conta anche come ti senti.": "It's an estimate: for some people it's off by 10 beats or more, so how you feel matters too.",
"Frasi di incoraggiamento durante lo sforzo hanno fatto durare di più e sentire meno fatica.": "Words of encouragement during effort made people last longer and feel less tired.",
"L'app ti confronta solo con te stesso, con le tue corse passate.": "The app only compares you with yourself, with your past runs.",
"Se hai problemi di cuore, pressione alta, dolori o non ti alleni da tanto, senti prima il medico.": "If you have heart problems, high blood pressure, pain or haven't trained in a long time, see a doctor first.",
"Se senti dolore al petto, giramenti di testa o fiato che non torna, fermati.": "If you feel chest pain, dizziness or breath that won't come back, stop.",
