"Bentornato!": "Welcome back!",
"È passato un po' di tempo, ed è normale: conta che sei qui.": "It's been a while, and that's normal: what matters is that you're here.",
"Oggi riparti con calma, anche con pesi più leggeri.": "Today start again gently, even with lighter weights.",
