"Il volume che cambio è quello della musica e della voce dell'app: il volume generale del telefono si cambia solo con i tasti": "I change the volume of the app's music and voice: the phone's overall volume can only be changed with its buttons",
"La tua sagoma": "Your body shape",
"Facoltativo. Tocca la figura più simile a te oggi e quella che vorresti. Nessuna foto: scegli tu, e resta solo sul telefono. Il coach la unisce a peso, altezza e giro vita.": "Optional. Tap the figure most like you today and the one you would like to be. No photos: you choose, and it stays only on your phone. The coach combines it with weight, height and waist.",
"Figure uomo": "Male figures",
"Figure donna": "Female figures",
"Figure": "Figures",
"Come sei oggi": "How you are today",
"Come vorresti essere": "How you would like to be",
"Figura {*}": "Figure {*}",
"Cancella le sagome": "Clear body shapes",
"Le figure servono a orientarti, non a misurarti: la corrispondenza con il peso è una": "The figures are a guide, not a measurement: the link with weight is an",
"dagli studi sulla scala di Stunkard.": "from studies on the Stunkard scale.",
"Ti vedi più robusto di quanto dicono i numeri.": "You see yourself as bigger than the numbers say.",
"Hai scelto la figura {*}, ma con il tuo peso e la tua altezza (IMC {*}) la figura più vicina è la {*}. Capita spesso: tendiamo a vederci diversi da come siamo. Se il tuo corpo ti preoccupa molto, parlane con il medico.": "You chose figure {*}, but with your weight and height (BMI {*}) the closest figure is {*}. This is common: we tend to see ourselves differently from how we are. If your body worries you a lot, talk to your doctor.",
"Ti vedi più magro di quanto dicono i numeri.": "You see yourself as slimmer than the numbers say.",
"Hai scelto la figura {*}, ma con il tuo peso e la tua altezza (IMC {*}) la figura più vicina è la {*}. Se hai molti muscoli può essere normale; altrimenti guarda anche il giro vita.": "You chose figure {*}, but with your weight and height (BMI {*}) the closest figure is {*}. If you have a lot of muscle this can be normal; otherwise also check your waist.",
"Per arrivare alla sagoma che vuoi.": "To reach the shape you want.",
"Il primo traguardo utile è perdere il 5–10% del peso (per te {*}–{*} kg): già così migliorano pressione, zuccheri e grassi nel sangue.{*} Fallo con calma, 0,5–1% a settimana, insieme al nutrizionista.{*}": "The first useful milestone is losing 5–10% of your weight ({*}–{*} kg for you): that alone improves blood pressure, blood sugar and blood fats.{*} Do it calmly, 0.5–1% a week, together with your nutritionist.{*}",
"Il primo traguardo utile è perdere il 5–10% del peso: già così migliorano pressione, zuccheri e grassi nel sangue.{*} Fallo con calma, 0,5–1% a settimana, insieme al nutrizionista.{*}": "The first useful milestone is losing 5–10% of your weight: that alone improves blood pressure, blood sugar and blood fats.{*} Do it calmly, 0.5–1% a week, together with your nutritionist.{*}",
" E porta il giro vita sotto {*} cm.": " And bring your waist under {*} cm.",
"E porta il giro vita sotto {*} cm.": "And bring your waist under {*} cm.",
"Ti consiglio di aggiungere l'obiettivo Dimagrire.": "I suggest adding the Lose weight goal.",
"Cambiare forma senza dimagrire troppo.": "Change shape without losing too much weight.",
"Il tuo peso è già nella norma. Più che perdere chili, gli esercizi con i pesi e abbastanza proteine cambiano la forma del corpo: meno grasso e più muscolo allo stesso peso.": "Your weight is already normal. Rather than losing kilos, weight training and enough protein change your body shape: less fat and more muscle at the same weight.",
"Per una sagoma più piena.": "For a fuller shape.",
"Per mettere su peso in modo sano servono muscoli, non solo calorie: allenamento con i pesi 2–3 volte a settimana, almeno 10 serie per muscolo e proteine a sufficienza.": "To gain weight healthily you need muscle, not just calories: weight training 2–3 times a week, at least 10 sets per muscle and enough protein.",
"Per una sagoma più grande.": "For a bigger shape.",
"Se vuoi sembrare più grosso senza ingrassare, punta sui muscoli: pesi, almeno 10 serie per muscolo a settimana e proteine. Il grasso in più non serve.": "If you want to look bigger without gaining fat, focus on muscle: weights, at least 10 sets per muscle a week and protein. Extra fat doesn't help.",
"Ti piaci così.": "You like yourself as you are.",
"La sagoma che vuoi è quella che hai già: ottimo. Allenati per stare bene, diventare più forte e mantenere quello che hai.": "The shape you want is the one you already have: great. Train to feel good, get stronger and keep what you have.",
"Attenzione a non esagerare.": "Be careful not to overdo it.",
"Vorresti una sagoma molto più magra, ma il tuo peso è già nella norma. Diete drastiche possono far male: se il pensiero del peso ti pesa, parlane con il medico.": "You would like a much slimmer shape, but your weight is already normal. Drastic diets can be harmful: if thinking about your weight weighs on you, talk to your doctor.",
"+ Aggiungi obiettivo {*}": "+ Add goal {*}",
