"Nella media": "Average",
"Snello": "Slim",
"Magro": "Thin",
"Molto magro": "Very thin",
"Figura {*}: {*}": "Figure {*}: {*}",
"Hai scelto la {*}:": "You chose {*}:",
"1 molto magro · 2 magro · 3 snello · 4 nella media · 5 atletico · 6 muscoloso · 7 molto muscoloso · 8 leggero sovrappeso · 9 sovrappeso · 10 obeso": "1 very thin · 2 thin · 3 slim · 4 average · 5 athletic · 6 muscular · 7 very muscular · 8 slightly overweight · 9 overweight · 10 obese",
"Muscoli sì, ma il giro vita è alto.": "Muscles yes, but your waist is high.",
"Ti vedi {*}, ma il giro vita ({*} cm) è più della metà dell'altezza: c'è un po' di grasso sulla pancia da togliere. I muscoli restano, il grasso si può ridurre.": "You see yourself as {*}, but your waist ({*} cm) is more than half your height: there is some belly fat to lose. The muscles stay, the fat can go down.",
"Ti vedi più muscoloso di quanto dicono i numeri.": "You see yourself as more muscular than the numbers say.",
"Con il tuo peso e la tua altezza (IMC {*}) la figura più vicina è la {*}. Per arrivarci servono più muscoli: pesi e proteine.": "With your weight and height (BMI {*}) the closest figure is {*}. To get there you need more muscle: weights and protein.",
"Hai scelto la figura {*} ({*}), ma con il tuo peso e la tua altezza (IMC {*}) la figura più vicina è la {*} ({*}). Capita spesso: tendiamo a vederci diversi da come siamo. Se il tuo corpo ti preoccupa molto, parlane con il medico.": "You chose figure {*} ({*}), but with your weight and height (BMI {*}) the closest figure is {*} ({*}). This is common: we tend to see ourselves differently from how we are. If your body worries you a lot, talk to your doctor.",
"Hai scelto la figura {*} ({*}), ma con il tuo peso e la tua altezza (IMC {*}) la figura più vicina è la {*} ({*}). Se hai molti muscoli può essere normale: in quel caso scegli la 5, 6 o 7. Altrimenti guarda anche il giro vita.": "You chose figure {*} ({*}), but with your weight and height (BMI {*}) the closest figure is {*} ({*}). If you have a lot of muscle this can be normal: in that case choose 5, 6 or 7. Otherwise also check your waist.",
"Per avere ancora più muscoli.": "For even more muscle.",
"Aumenta poco alla volta le serie (fino a circa 20 a settimana per muscolo), arriva vicino alla fatica vera e mangia abbastanza proteine. Dopo i primi anni i muscoli crescono più lentamente: serve pazienza.": "Increase sets little by little (up to about 20 a week per muscle), get close to real fatigue and eat enough protein. After the first years muscles grow more slowly: be patient.",
"Per diventare {*}.": "To become {*}.",
"Servono due cose insieme: meno grasso e più muscoli. Prima perdi il 5–10% del peso{*} con calma, 0,5–1% a settimana, insieme al nutrizionista{*}. Nel frattempo pesi 2–3 volte a settimana, almeno 10 serie per muscolo e proteine: così perdi grasso e tieni o aumenti i muscoli.": "You need two things together: less fat and more muscle. First lose 5–10% of your weight{*} calmly, 0.5–1% a week, with your nutritionist{*}. Meanwhile weights 2–3 times a week, at least 10 sets per muscle and protein: this way you lose fat and keep or build muscle.",
" (per te {*}–{*} kg)": " ({*}–{*} kg for you)",
", e porta il giro vita sotto {*} cm": ", and bring your waist under {*} cm",
"Il tuo peso va già bene: ora servono più muscoli. Pesi 2–3 volte a settimana, almeno 10 serie per muscolo, vicino alla fatica vera, e proteine a sufficienza. Si vede la differenza in qualche mese.": "Your weight is already fine: now you need more muscle. Weights 2–3 times a week, at least 10 sets per muscle, close to real fatigue, and enough protein. You will see the difference in a few months.",
"Attenzione alla salute.": "Mind your health.",
"La sagoma che hai scelto ha più grasso di quella di oggi: per la salute non conviene. Se vuoi sembrare più grosso, punta sui muscoli (figure 5–7).": "The shape you chose has more fat than today's: it is not good for your health. If you want to look bigger, focus on muscle (figures 5–7).",
"Molto muscoloso: senza scorciatoie.": "Very muscular: no shortcuts.",
"Un fisico da culturista richiede anni di allenamento costante. Evita anabolizzanti e ormoni: danneggiano cuore, fegato e ormoni, anche in modo permanente.": "A bodybuilder's physique takes years of steady training. Avoid anabolic steroids and hormones: they damage heart, liver and hormones, sometimes permanently.",
"Una sagoma meno muscolosa.": "A less muscular shape.",
"Basta ridurre le serie con i pesi e fare più attività aerobica: i muscoli calano piano. Per restare in salute tieni comunque 2 allenamenti di forza a settimana.": "Just cut back on weight sets and do more aerobic activity: muscles shrink slowly. To stay healthy, still keep 2 strength sessions a week.",
"La differenza è soprattutto nei muscoli: allenati con i pesi 2–3 volte a settimana, almeno 10 serie per muscolo, e mangia abbastanza proteine.": "The difference is mostly muscle: train with weights 2–3 times a week, at least 10 sets per muscle, and eat enough protein.",
